window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-155"]=[{"id":"set2-7aKJAPnQ","fingerprint":"2cd3d5c5c19addeb","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt caracteristicile definitorii ale tumorilor maligne?","options":[{"id":"A","text":"Creșterea de tip expansiv, cu prezența unei capsule bine definite."},{"id":"B","text":"Abilitatea de a invada țesuturile de vecinătate."},{"id":"C","text":"Diviziunea necontrolată a celulelor."},{"id":"D","text":"Diseminarea exclusiv pe cale hematogenă la distanță."},{"id":"E","text":"Capacitatea de a metastaza pe cale limfatică sau hematogenă."}],"correct":["B","C","E"],"pages":[645],"source":"set-2"},{"id":"set2-x4wscuQ-","fingerprint":"57d36a00a17f68f1","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care este considerat cel mai semnificativ factor de prognostic în cancerul oral incipient?","options":[{"id":"A","text":"Dimensiunea tumorii primare."},{"id":"B","text":"Metastaza ganglionară."},{"id":"C","text":"Gradul de diferențiere tumorală."},{"id":"D","text":"Localizarea tumorii la nivelul planșeului bucal."},{"id":"E","text":"Vârsta pacientului la momentul diagnosticării."}],"correct":["B"],"pages":[645],"source":"set-2"},{"id":"set2-3tjlNfUm","fingerprint":"d8f25dd963f7d660","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Cu ce procent scade rata de supraviețuire în cazul cancerului oral în prezența adenopatiei metastatice N1?","options":[{"id":"A","text":"Scade cu peste 50%."},{"id":"B","text":"Scade cu 20-40%."},{"id":"C","text":"Scade cu aproximativ 10%."},{"id":"D","text":"Rata de supraviețuire nu este influențată semnificativ."},{"id":"E","text":"Scade cu mai puțin de 5%."}],"correct":["A"],"pages":[645],"source":"set-2"},{"id":"set2-qc1HGj3D","fingerprint":"62633c0b456d2db6","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce proporție din totalitatea limfonodulilor organismului este situată la nivelul gâtului?","options":[{"id":"A","text":"Aproximativ jumătate."},{"id":"B","text":"Aproximativ o treime."},{"id":"C","text":"Sub 10%."},{"id":"D","text":"Aproximativ un sfert."},{"id":"E","text":"Peste două treimi."}],"correct":["B"],"pages":[645],"source":"set-2"},{"id":"set2-W2fyiu-4","fingerprint":"f610bc562371e902","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afirmații referitoare la principiile tratamentului chirurgical cu intenție curativă sunt corecte?","options":[{"id":"A","text":"Plastia reconstructivă imediată este contraindicată, deoarece întârzie vindecarea și începerea radioterapiei."},{"id":"B","text":"Intervenția chirurgicală cuprinde extirparea tumorii și evidarea cervicală, reconstrucția fiind o etapă secundară, amânată."},{"id":"C","text":"Metoda de plastie reconstructivă se alege înaintea extirpării tumorii."},{"id":"D","text":"Se preferă plastia reconstructivă imediată pentru a putea iniția rapid radioterapia post-operatorie."},{"id":"E","text":"Nu se fac compromisuri excizionale pentru a favoriza plastia reconstructivă."}],"correct":["C","D","E"],"pages":[645],"source":"set-2"},{"id":"set2-zpkwh8Jx","fingerprint":"7b52c3762e746a9b","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt obiectivele principale ale tratamentului în cazul tumorilor maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Limitarea tratamentului exclusiv la chimioterapie pentru a evita desfigurarea."},{"id":"B","text":"Începerea tratamentului doar după obținerea unei remisii parțiale spontane."},{"id":"C","text":"Asigurarea supraviețuirii la 5 ani după finalizarea tratamentului."},{"id":"D","text":"Reintegrarea socială a pacientului, chiar cu sacrificarea completă a funcționalității."},{"id":"E","text":"Asigurarea calității vieții prin reabilitare funcțională."}],"correct":["C","E"],"pages":[645],"source":"set-2"},{"id":"set2--ytmdskQ","fingerprint":"d6e1306487d18d18","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce caracteristici epidemiologice definesc tumorile maligne ale roșului de buză?","options":[{"id":"A","text":"Sunt localizate în peste 80% din cazuri la buza inferioară."},{"id":"B","text":"Predomină la sexul masculin, dar sunt mai frecvente la buza superioară."},{"id":"C","text":"Sunt mai frecvente în intervalul de vârstă 20-30 de ani."},{"id":"D","text":"Apar mai frecvent la sexul feminin."},{"id":"E","text":"Afectează în mod egal buza superioară și cea inferioară."}],"correct":["A"],"pages":[645],"source":"set-2"},{"id":"set2-scfnWPjh","fingerprint":"33982164ff37ee9b","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt formele clinice pe care le pot îmbrăca tumorile maligne de buză în perioada de stare?","options":[{"id":"A","text":"Forma eroziv-ulcerativă"},{"id":"B","text":"Forma ulcero-vegetantă (exofitică)"},{"id":"C","text":"Forma ulcero-distructivă"},{"id":"D","text":"Forma terebrantă"},{"id":"E","text":"Forma nodulară"}],"correct":["B","C"],"pages":[646],"source":"set-2"},{"id":"set2-VGMdqUA2","fingerprint":"09de2dcec0e58596","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afecțiuni intră în diagnosticul diferențial al unei tumori maligne de buză?","options":[{"id":"A","text":"Ulcerațiile herpetice"},{"id":"B","text":"Șancrul primar"},{"id":"C","text":"Papilomul"},{"id":"D","text":"Cheilitele microbiene sau chimice"},{"id":"E","text":"Leucoplazia orală"}],"correct":["A","B","C","D"],"pages":[646],"source":"set-2"},{"id":"set2-aBvCv6CY","fingerprint":"5ee73b6c2c7745c8","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Cum se realizează afectarea osoasă mandibulară pe cale indirectă în evoluția tumorilor maligne ale buzei?","options":[{"id":"A","text":"Prin intermediul unei adenopatii submandibulare secundare, fixate, care invadează osul."},{"id":"B","text":"Prin invazia osului din aproape în aproape, cu extensie de-a lungul canalului mandibular."},{"id":"C","text":"Prin metastaze la distanță care se localizează secundar la nivelul mandibulei."},{"id":"D","text":"Prin invazia directă a părților moi labio-geniene care erodează ulterior arcul osos mentonier."},{"id":"E","text":"Prin extensia tumorii de pe fața mucozală a buzei direct pe arcul osos."}],"correct":["A"],"pages":[646],"source":"set-2"},{"id":"set2-McuyhfTM","fingerprint":"be638aefaf84b4cd","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt afirmațiile corecte referitoare la afectarea metastatică a limfonodulilor în tumorile maligne ale buzelor?","options":[{"id":"A","text":"Apariția metastazelor cervicale este un fenomen precoce în evoluția bolii."},{"id":"B","text":"Incidența ganglionilor cervicali palpabili la primul consult este de 10-15%."},{"id":"C","text":"Nivelul cervical cel mai frecvent interesat inițial este nivelul II."},{"id":"D","text":"În cazul recidivelor tumorii primare, incidența metastazelor ganglionare cervicale crește până la 30%."},{"id":"E","text":"În decurs de doi ani, metastazele cervicale apar la aproximativ 50% dintre pacienți."}],"correct":["B","D"],"pages":[646],"source":"set-2"},{"id":"set2-m71DPfFa","fingerprint":"7dc91a63f08079a2","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce caracterizează evoluția clinică a tumorilor maligne ale limbii și planșeului oral în fazele de debut?","options":[{"id":"A","text":"Evoluție relativ asimptomatică, dar cu caracter invaziv și limfofil marcat."},{"id":"B","text":"Debut exclusiv sub formă de leziuni ulcerative pe un fond normal al mucoasei."},{"id":"C","text":"Caracter limfofil redus, cu adenopatii metastatice rare la primul consult."},{"id":"D","text":"Afectarea stării generale încă din stadiile incipiente ale bolii."},{"id":"E","text":"Evoluție rapid simptomatică, cu durere intensă de la început."}],"correct":["A"],"pages":[646],"source":"set-2"},{"id":"set2-7sBnhHBX","fingerprint":"af48a4c4edce7c22","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt formele de debut ale tumorilor maligne ale limbii și planșeului bucal?","options":[{"id":"A","text":"Forma nodulară intraparenchimatoasă"},{"id":"B","text":"Forma eroziv-ulcerativă"},{"id":"C","text":"Leziuni ulcerative"},{"id":"D","text":"Forma vegetantă"},{"id":"E","text":"Forma terebrantă"}],"correct":["A","C","D"],"pages":[646],"source":"set-2"},{"id":"set2-_Pzw9KsX","fingerprint":"1b4b8df85490d06f","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"În cadrul diagnosticului diferențial al tumorilor maligne de buză, ce element clinic este caracteristic șancrului primar?","options":[{"id":"A","text":"Ulcerație cu margini suple, acoperită de depozite murdare."},{"id":"B","text":"Prezența perilezională a unor granulații gălbui."},{"id":"C","text":"Apariția unor erupții veziculoase premergătoare ulcerației."},{"id":"D","text":"Remiterea ulcerației în cel mult 14 zile."},{"id":"E","text":"Ulcerație cu bază indurată, cartonată și fund de culoare roșie intensă."}],"correct":["E"],"pages":[646],"source":"set-2"},{"id":"set2-DJuoT_0X","fingerprint":"bc2a680ee55cb93b","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt localizările cele mai frecvente pentru debutul tumorilor maligne la nivelul limbii?","options":[{"id":"A","text":"Fața dorsală a limbii"},{"id":"B","text":"Șanțul pelvilingual"},{"id":"C","text":"Vârful limbii"},{"id":"D","text":"Marginea laterală a limbii"},{"id":"E","text":"Fața ventrală a limbii"}],"correct":["B","D","E"],"pages":[647],"source":"set-2"},{"id":"set2-UY1QLfAU","fingerprint":"a708f2f4fee1cd53","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce element clinic poate orienta diagnosticul în cazul unei tumori maligne localizate paramedian în porțiunea anterioară a planșeului bucal?","options":[{"id":"A","text":"O formă predominant proliferativă"},{"id":"B","text":"Evoluția lentă și infiltrativă"},{"id":"C","text":"Aspectul de „carte deschisă”"},{"id":"D","text":"Prezența leziunii pe un fond leucoplazic"},{"id":"E","text":"Localizarea în șanțul amigdaloglos"}],"correct":["D"],"pages":[647],"source":"set-2"},{"id":"set2-eS_mSKU_","fingerprint":"0a7587515a11e73b","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care formă clinică a tumorilor maligne orale este specifică doar localizărilor intraparenchimatoase linguale?","options":[{"id":"A","text":"Leziunea ulcerativă pe fond leucoplazic"},{"id":"B","text":"Forma ulcero-vegetantă"},{"id":"C","text":"Tumora pelvilinguală „în foaie de carte”"},{"id":"D","text":"Forma ulcero-distructivă"},{"id":"E","text":"Forma infiltrativă, scleroasă (schiroasă)"}],"correct":["E"],"pages":[647],"source":"set-2"},{"id":"set2-Kn88Eagi","fingerprint":"c82ef8ec4c2adefc","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Conform studiilor clinico-statistice, care afirmații privind repartiția tumorilor maligne linguale sunt corecte?","options":[{"id":"A","text":"Majoritatea tumorilor cu evoluție intraparenchimatoasă debutează pe vârful limbii."},{"id":"B","text":"25% dintre tumori se localizează pe fața dorsală a limbii."},{"id":"C","text":"Localizările de pe fața ventrală a limbii sunt cele mai rare."},{"id":"D","text":"50% dintre tumorile localizate anterior afectează marginile limbii."},{"id":"E","text":"75% dintre tumori afectează cele două treimi anterioare ale limbii."}],"correct":["D","E"],"pages":[647],"source":"set-2"},{"id":"set2-G1dD2azP","fingerprint":"5f90935be3d50859","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce caracteristici definitorii prezintă tumorile maligne ale porțiunii post-sulcale a limbii?","options":[{"id":"A","text":"Manifestările subiective includ jena în deglutiție, care ulterior poate fi însoțită de disfagie și durere."},{"id":"B","text":"Debutul este insidios, iar diagnosticul este pus frecvent în stadii avansate."},{"id":"C","text":"Simptomatologia inițială include durere acută și sângerare spontană."},{"id":"D","text":"Au un grad redus de malignitate locală și metastazează tardiv."},{"id":"E","text":"Examenul clinic este simplu și relevă leziuni ulcerative clare de la început."}],"correct":["A","B"],"pages":[647],"source":"set-2"},{"id":"set2-lsvm8Kdv","fingerprint":"8d1436b098cb74e2","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce ganglion limfatic este considerat patognomonic în tumorile maligne de limbă și planșeu bucal, având în vedere că drenează anatomic porțiunea posterioară a limbii?","options":[{"id":"A","text":"Ganglionul submandibular"},{"id":"B","text":"Ganglionul supraomohioidian"},{"id":"C","text":"Ganglionul retrodigastric (Kuttner I)"},{"id":"D","text":"Ganglionul amigdaloglos"},{"id":"E","text":"Ganglionul submental"}],"correct":["C"],"pages":[647],"source":"set-2"},{"id":"set2-1gKNKUT9","fingerprint":"696e7e4472665a9a","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce examen de specialitate se impune in cazurile de suspiciune a unei tumori in portiunea post-sulcala a limbii, pentru evidentierea leziunilor prin mijloace complementare tehnice de examinare?","options":[{"id":"A","text":"Examenul ORL"},{"id":"B","text":"Examenul clinic prin palpare bimanuală"},{"id":"C","text":"Examenul radiologic panoramic"},{"id":"D","text":"Tomografia computerizată"},{"id":"E","text":"Biopsia incizională directă"}],"correct":["A"],"pages":[647],"source":"set-2"},{"id":"set2-rmsqudZK","fingerprint":"4586b60ac659e1d3","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce proporție de pacienți cu tumori maligne ale limbii și planșeului bucal prezentau adenopatie cervicală la primul consult de specialitate, conform unui studiu realizat în Clinica de Chirurgie Maxilo-Facială din București?","options":[{"id":"A","text":"O treime (1/3)"},{"id":"B","text":"Jumătate (1/2)"},{"id":"C","text":"Un sfert (1/4)"},{"id":"D","text":"Două treimi (2/3)"},{"id":"E","text":"Trei sferturi (3/4)"}],"correct":["D"],"pages":[647],"source":"set-2"},{"id":"set2-9JbtbqOs","fingerprint":"6806f1cc057fb91a","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Un pacient prezintă o ulcerație pe fața dorsală a limbii, dureroasă spontan, cu granulații gălbui perilezional și o bază suplă la palpare. Care afecțiune benignă trebuie luată în considerare în diagnosticul diferențial cu o tumoră malignă?","options":[{"id":"A","text":"Ulcerația traumatică"},{"id":"B","text":"Sifilisul primar"},{"id":"C","text":"Ulcerația tuberculoasă"},{"id":"D","text":"Afta bucală"},{"id":"E","text":"Litiaza canalului Wharton"}],"correct":["C"],"pages":[648],"source":"set-2"},{"id":"set2-F0mOjHIz","fingerprint":"a8cf055db0d4c4df","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt afirmațiile corecte referitoare la evoluția tumorilor maligne ale limbii și planșeului bucal?","options":[{"id":"A","text":"Limitarea actelor funcționale poate duce la o formă gravă de „anchiloză pelvi-linguală” cu afectare funcțională majoră."},{"id":"B","text":"Evoluția este de regulă lentă, permițând o adaptare funcțională îndelungată."},{"id":"C","text":"Extensia tumorală se limitează strict la țesuturile moi, fără a invada structurile osoase."},{"id":"D","text":"Durerea este un simptom precoce și se accentuează prin invazia nervilor lingual și glosofaringian."},{"id":"E","text":"Adenopatia apare tardiv, doar în stadiile avansate ale bolii."}],"correct":["A","D"],"pages":[648],"source":"set-2"},{"id":"set2-KCPWAmkj","fingerprint":"517a8a1827d564a2","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt formele de debut ale tumorilor maligne primare ale mucoasei gingivale?","options":[{"id":"A","text":"Forma vegetantă"},{"id":"B","text":"Forma ulcero-vegetantă"},{"id":"C","text":"Forma ulcerativă"},{"id":"D","text":"Forma ulcero-distructivă"},{"id":"E","text":"Forma chistică"}],"correct":["A","C"],"pages":[648],"source":"set-2"},{"id":"set2-IbGKTAe5","fingerprint":"df75f29e33b9f37a","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"La un pacient dentat, o tumoră malignă a mucoasei gingivale în formă vegetantă poate fi confundată cu care dintre următoarele afecțiuni?","options":[{"id":"A","text":"Epulis"},{"id":"B","text":"Chist al planșeului bucal"},{"id":"C","text":"Gingivită hiperplazică"},{"id":"D","text":"Abces al lojei sublinguale"},{"id":"E","text":"Leziuni fibro-epiteliale sesile"}],"correct":["A","C","E"],"pages":[648],"source":"set-2"},{"id":"set2-hxJZEtGF","fingerprint":"43fc8d2eb27e415b","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce particularitate clinică la un pacient edentat poate sugera natura malignă a unei ulcerații la nivelul crestei alveolare, diferențiind-o de o leziune de decubit protetic?","options":[{"id":"A","text":"Prezența unei colici salivare în legătură cu orarul meselor."},{"id":"B","text":"Fundul neted și curat al ulcerației, cu bază indurată limitat."},{"id":"C","text":"Remiterea leziunii în 7-10 zile după îndepărtarea protezei."},{"id":"D","text":"Durerea extrem de intensă la palpare, disproporționată față de mărimea leziunii."},{"id":"E","text":"Prezența adiacentă sau inclavarea într-o arie leucoplazică."}],"correct":["E"],"pages":[648],"source":"set-2"},{"id":"set2-Bqq20MSe","fingerprint":"c86dbd4c70297b63","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"În perioada de stare, care este mecanismul de invazie osoasă și consecința sa radiologică în cazul formei ulcero-distructive a tumorilor maligne gingivale?","options":[{"id":"A","text":"Tumora invadează osul prin resorbție lentă, determinând un aspect de os suflat, radioopac."},{"id":"B","text":"Tumora nu invadează osul, ci se extinde doar în suprafață, către țesuturile moi adiacente."},{"id":"C","text":"Extensia tumorală se face de-a lungul ligamentului parodontal, cauzând doar mobilitate dentară, fără osteoliză."},{"id":"D","text":"Invazia osoasă este rară și se manifestă prin reacție periostală, fără distrucție osoasă evidentă."},{"id":"E","text":"Invazia se produce prin spațiul parodontal, ducând la o osteoliză cu aspect crateriform."}],"correct":["E"],"pages":[648],"source":"set-2"},{"id":"set2-8YXEbK8p","fingerprint":"af740e4f23a9cfe6","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt afirmațiile adevărate privind epidemiologia și caracteristicile carcinoamelor orale?","options":[{"id":"A","text":"Rata metastazelor oculte în cancerul oral incipient este estimată între 20-40%."},{"id":"B","text":"Rata de supraviețuire scade cu peste 50% în contextul prezenței adenopatiei metastatice în N1."},{"id":"C","text":"Aproximativ o treime din totalitatea limfonodulilor sunt situați la nivelul gâtului."},{"id":"D","text":"Aproape 40-50% dintre bolnavi se prezintă în stadiul III sau IV."},{"id":"E","text":"Cea mai frecventă localizare este planșeul bucal, urmată de limbă."}],"correct":["A","B","C"],"pages":[645],"source":"set-2"},{"id":"set2-cKy3UK4w","fingerprint":"ad634fabd500f670","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt principiile generale ale tratamentului chirurgical cu intenție curativă în tumorile maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Intervenția chirurgicală cuprinde extirparea tumorii primare, plastia reconstructivă și conduita terapeutică față de limfonodulii cervicali."},{"id":"B","text":"Plastia reconstructivă imediată este preferată pentru a iniția cât mai repede radioterapia post-operatorie."},{"id":"C","text":"Metoda de plastie reconstructivă se alege înainte de extirparea tumorii, deoarece influențează tiparul extirpării."},{"id":"D","text":"Extirparea tumorii primare se realizează cu limite de siguranță oncologică, admițându-se margini libere pozitive."},{"id":"E","text":"Se pot face compromisuri excizionale în favoarea plastiei reconstructive pentru o refacere rapidă a fizionomiei."}],"correct":["A","B","C"],"pages":[645],"source":"set-2"},{"id":"set2-oMOxhu3c","fingerprint":"40484db82d4295ea","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt obiectivele și particularitățile abordării terapeutice în tumorile maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Tratamentul multimodal este complex și include tratamentul chirurgical, tratamentul asociat, imunoterapia și tratamentele de susținere."},{"id":"B","text":"Asigurarea calității vieții se bazează pe reabilitarea funcțională care să permită reintegrarea socială."},{"id":"C","text":"Secvențialitatea etapelor de tratament se determină exclusiv pe baza investigațiilor paraclinice, independent de acceptul pacientului."},{"id":"D","text":"Asigurarea vindecării presupune supraviețuirea la 5 ani după începerea tratamentului."},{"id":"E","text":"Conduita terapeutică se stabilește printr-o decizie unilaterală de către medicul chirurg oro-maxilo-facial."}],"correct":["A","B"],"pages":[645],"source":"set-2"},{"id":"set2-o8RL-uYQ","fingerprint":"287174b9beba4b71","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele elemente caracterizează patologia și diseminarea tumorilor maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Diseminarea celulelor neoplazice se realizează pe cale limfatică sau hematogenă, loco-regional sau la distanță."},{"id":"B","text":"Teritoriul oro-maxilo-facial deține un drenaj limfatic limitat, ganglionii gâtului reprezentând sub 10% din totalul limfonodulilor."},{"id":"C","text":"Celulele tumorale dispun de abilitatea de a invada din aproape în aproape țesuturile de vecinătate."},{"id":"D","text":"Metastazele sunt structuri tumorale având o conformație histologică complet diferită de tumora primară."},{"id":"E","text":"Creșterea tumorală este de tip infiltrativ-distructiv, cu invazie locală."}],"correct":["A","C","E"],"pages":[645],"source":"set-2"},{"id":"set2-00aQ-9zF","fingerprint":"5e9c549043851614","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care este cel mai semnificativ factor de prognostic în cancerul oral?","options":[{"id":"A","text":"Rata metastazelor oculte în stadiul incipient de boală."},{"id":"B","text":"Localizarea tumorii primare la nivelul limbii."},{"id":"C","text":"Metastaza ganglionară."},{"id":"D","text":"Prezentarea clinică inițială a pacientului în stadiul I sau II."},{"id":"E","text":"Invazia țesuturilor de vecinătate din aproape în aproape."}],"correct":["C"],"pages":[645],"source":"set-2"},{"id":"set2-sGdvv1Tv","fingerprint":"f6f2f60f15cfe960","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care sunt caracteristicile epidemiologice și de debut ale tumorilor maligne de roșu de buză?","options":[{"id":"A","text":"Elementul clinic ce orientează diagnosticul prezumtiv în stadiile de debut este localizarea paramediană a tumorii."},{"id":"B","text":"Predomină la pacienții de sex feminin."},{"id":"C","text":"Apar cel mai frecvent la adulții tineri, cu vârste cuprinse între 20 și 30 de ani."},{"id":"D","text":"Debutul are loc exclusiv sub formă de ulcerație profundă, rapid invazivă."},{"id":"E","text":"Se localizează în peste 80% din cazuri la nivelul buzei superioare."}],"correct":["A"],"pages":[646],"source":"set-2"},{"id":"set2-AsLjgzKW","fingerprint":"513ec4367710e435","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Diagnosticul diferențial al tumorilor maligne de buză impune excluderea unor afecțiuni specifice, caracterizate prin trăsături clinice particulare, printre care:","options":[{"id":"A","text":"Șancrul primar, caracterizat printr-o ulcerație cu bază indurată, cartonată și un fund de culoare roșie intensă."},{"id":"B","text":"Ulcerațiile herpetice, care se disting prin prezența unor margini indurate și evoluție cronică nedeterminată."},{"id":"C","text":"Șancrul primar, deosebindu-se prin prezența unei suprafețe acoperite de depozite murdare."},{"id":"D","text":"Cheilitele microbiene sau chimice, care din punct de vedere clinic se pot confunda cu formele infiltrative ale tumorii."},{"id":"E","text":"Ulcerațiile tuberculoase, prezentând perilezional granulații gălbui specifice."}],"correct":["A","D","E"],"pages":[646],"source":"set-2"},{"id":"set2-KLx5_7nR","fingerprint":"42b8b6aca5650dbe","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Afectarea osoasă mandibulară în evoluția tumorilor maligne de buză se realizează pe cale:","options":[{"id":"A","text":"Indirectă, prin intermediul unei adenopatii submandibulare secundare fixate, care efracționează periostul și invadează corticala osoasă."},{"id":"B","text":"Directă, prin invazia osului din aproape în aproape, cu extensie de-a lungul canalului mandibular și implicarea pachetului vasculo-nervos."},{"id":"C","text":"Indirectă, prin diseminare hematogenă rapidă la nivelul unghiului mandibular."},{"id":"D","text":"Limfatică retrogradă, având drept consecință afectarea primară a articulației temporo-mandibulare."},{"id":"E","text":"Directă, prin producerea unor metastaze periapicale specifice la nivelul dinților frontali maxilari."}],"correct":["A","B"],"pages":[646],"source":"set-2"},{"id":"set2-IXn_fIk8","fingerprint":"8ccc22c6a8691981","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care dintre următoarele afirmații descrie comportamentul metastatic și evoluția adenopatiilor asociate tumorilor maligne de buză?","options":[{"id":"A","text":"Starea generală a pacientului suferă o deteriorare profundă încă din primele stadii incipiente de boală."},{"id":"B","text":"În eventualitatea unor recidive ale tumorii primare, incidența metastazelor ganglionare cervicale se menține la un prag de maximum 10-15%."},{"id":"C","text":"Apariția metastazelor cervicale în primul an de la diagnosticare se produce în aproximativ 25% din cazuri."},{"id":"D","text":"La momentul primului consult clinic, prezența ganglionilor cervicali palpabili are o incidență de aproximativ 80%."},{"id":"E","text":"Afectarea metastatică a limfonodulilor loco-regionali implică predominant nivelul III cervical."}],"correct":["C"],"pages":[646],"source":"set-2"},{"id":"set2-Jhj_-QP0","fingerprint":"40ece85dfe5c0340","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"În perioada de stare, tumorile maligne de buză pot îmbrăca următoarele forme clinice:","options":[{"id":"A","text":"Forma eritemato-veziculoasă."},{"id":"B","text":"Forma ulcero-vegetantă (exofitică)."},{"id":"C","text":"Forma ulcero-distructivă."},{"id":"D","text":"Forma nodular-chistică."},{"id":"E","text":"Forma terebrantă, considerată expresia clinică a unei tumori în stadiu avansat, care evoluează lent și se extinde masiv la persoanele în vârstă."}],"correct":["B","C"],"pages":[646],"source":"set-2"},{"id":"set2-MQSX6Ezt","fingerprint":"1b5f05e4930de5ad","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Despre debutul tumorilor maligne ale porțiunii orale a limbii și planșeului bucal sunt adevărate următoarele afirmații:","options":[{"id":"A","text":"La nivelul planșeului bucal, majoritatea tumorilor sunt localizate paramedian în porțiunea anterioară a acestuia."},{"id":"B","text":"Durerea apare inițial, în absența oricărei suprainfectări a leziunii."},{"id":"C","text":"Marginile laterale, vârful și fața dorsală a limbii reprezintă în mod egal localizările de debut cele mai frecvente."},{"id":"D","text":"Forma de debut nodulară are originea, de regulă, la nivelul glandelor salivare accesorii."},{"id":"E","text":"Se prezintă cel mai frecvent sub forma unor leziuni ulcerative, prezente adesea pe un fond leucoplazic."}],"correct":["A","D","E"],"pages":[646],"source":"set-2"},{"id":"set2-kFhPVHY_","fingerprint":"f41dab095de261d1","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care este afirmația adevărată privind formele clinice din perioada de stare a tumorilor maligne de limbă și planșeu bucal?","options":[{"id":"A","text":"Forma ulcero-vegetantă se observă predominant în localizările de la nivelul planșeului bucal."},{"id":"B","text":"Tumorile situate în porțiunea anterioară a limbii afectează în proporție de 50% fața dorsală a acesteia."},{"id":"C","text":"Tumorile maligne se prezintă în perioada de stare cel mai frecvent sub o formă proliferativă, de aspect eminamente nodular."},{"id":"D","text":"Forma infiltrativă, scleroasă (schiroasă) este o caracteristică exclusivă a localizărilor intraparenchimatoase linguale."},{"id":"E","text":"Aspectul în „foaie de carte” se referă la tumorile cu localizare strictă la nivelul marginii libere a limbii."}],"correct":["D"],"pages":[646],"source":"set-2"},{"id":"set2-a1-Cymim","fingerprint":"5ae2efc58380da47","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Alegeți afirmațiile adevărate referitoare la tumorile porțiunii post-sulcale a limbii:","options":[{"id":"A","text":"Din punct de vedere statistic, reprezintă aproximativ 75% din totalul tumorilor maligne linguale."},{"id":"B","text":"Manifestările clinice subiective includ inițial jena în deglutiție, iar într-o fază mai avansată, alături de disfagie, apare durerea."},{"id":"C","text":"Examenul clinic poate pune în evidență creșterea de volum a treimii posterioare a limbii, arie care devine dureroasă la presiune."},{"id":"D","text":"Prezintă o evoluție lentă, cu un grad redus de malignitate și o diagnosticare extrem de precoce."},{"id":"E","text":"Debutul acestor tumori este insidios, fiind de obicei diagnosticate tardiv, în stadii avansate de evoluție."}],"correct":["B","C","E"],"pages":[646],"source":"set-2"},{"id":"set2-gL4JKUG9","fingerprint":"9927e90222d8502d","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Referitor la extensia și implicarea ganglionară în tumorile maligne ale limbii și planșeului bucal, care este singura afirmație adevărată?","options":[{"id":"A","text":"Tumorile cu evoluție pelvi-linguală sunt net delimitate și nu se extind niciodată la nivelul mandibulei."},{"id":"B","text":"Apariția durerii precoce este mediată strict de invazia nervului facial, ducând rapid la o anchiloză pelvi-linguală."},{"id":"C","text":"Ganglionul supraomohioidian drenează din punct de vedere anatomic porțiunea anterioară a limbii și planșeul bucal anterior."},{"id":"D","text":"Ganglionul retrodigastric (Kuttner I) drenează din punct de vedere anatomic porțiunea anterioară a limbii."},{"id":"E","text":"Adenopatia apare de obicei tardiv, fiind independentă de profunzimea invaziei și de gradul de diferențiere tumorală."}],"correct":["C"],"pages":[646],"source":"set-2"},{"id":"set2-HFInzJro","fingerprint":"34d86a6fc0a8e650","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele elemente descriu corect entitățile luate în considerare în diagnosticul diferențial al tumorilor maligne ale limbii și planșeului bucal?","options":[{"id":"A","text":"Litiaza canalului Wharton generează colică salivară dependentă de orarul meselor și eliminarea de puroi la presiunea pe glanda submandibulară."},{"id":"B","text":"Chisturile planșeului bucal se diferențiază printr-o evoluție fulminantă, foarte rapidă și o consistență fermă, dură la palpare."},{"id":"C","text":"Sifilisul primar se prezintă sub forma unei ulcerații cu fundul neted, curat, a cărei bază prezintă o indurație limitată."},{"id":"D","text":"Aftele bucale reprezintă ulcerații de mici dimensiuni, strict nedureroase, care persistă peste 30 de zile."},{"id":"E","text":"Șancrul primar tuberculos prezintă perilezional granulațiile gălbui ale lui Trélat și are o bază suplă la palpare."}],"correct":["A","C","E"],"pages":[646],"source":"set-2"},{"id":"set2-JO9FRe0P","fingerprint":"664f64ed89210239","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt formele de debut ale tumorilor maligne primare ale mucoasei gingivale?","options":[{"id":"A","text":"Forma ulcerativă"},{"id":"B","text":"Forma vegetantă"},{"id":"C","text":"Forma ulcero-distructivă"},{"id":"D","text":"Forma ulcero-chistică"},{"id":"E","text":"Forma ulcero-vegetantă"}],"correct":["A","B"],"pages":[648],"source":"set-2"},{"id":"set2-bHMVCHBf","fingerprint":"de3160dab242d8f2","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce particularități clinice prezintă forma vegetantă papilomatoasă a tumorilor maligne gingivale la pacientul dentat?","options":[{"id":"A","text":"Devine infiltrativă pe parcursul evoluției, fixându-se de substratul osos."},{"id":"B","text":"Debutează cu o bază largă de implantare, cuprinzând multiple papile interdentare."},{"id":"C","text":"Mobilizarea dinților asociați este cauzată de proliferarea tumorală de-a lungul ligamentului parodontal."},{"id":"D","text":"Se pretează la confuzii de diagnostic clinic cu epulisul sau cu gingivita hiperplazică."},{"id":"E","text":"Evoluția sa induce anchiloza dinților adiacenți în procesul alveolar."}],"correct":["A","C","D"],"pages":[648],"source":"set-2"},{"id":"set2-tPEI_CYE","fingerprint":"b500c4dcf74cd18d","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Ce caracteristici de debut se pot observa la nivelul tumorilor maligne ale mucoasei gingivale la pacientul edentat?","options":[{"id":"A","text":"Debutul sub formă de ulcerație prezintă o simptomatologie dureroasă violentă."},{"id":"B","text":"Formele maligne incipiente se dezvoltă exclusiv pe o mucoasă gingivală indemnă, neafectată de alte leziuni precanceroase."},{"id":"C","text":"Tumora debutează exclusiv prin leziuni de tip vegetant localizate în zona papilelor interdentare atrofiate."},{"id":"D","text":"Ulcerația de debut este ușor de diferențiat clinic de leziunile de decubit provocate de protezele dentare."},{"id":"E","text":"Forma nodulară sau vegetantă dezvoltată pe creasta alveolară induce instabilitatea protezelor dentare."}],"correct":["E"],"pages":[648],"source":"set-2"},{"id":"set2-CFulKN1v","fingerprint":"13e715d3658ebc61","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Cum se caracterizează evoluția tumorilor maligne ale mucoasei gingivale pe parcursul perioadei de stare?","options":[{"id":"A","text":"Invazia osului subiacent se produce cel mai adesea prin intermediul spațiului parodontal."},{"id":"B","text":"În forma ulcero-distructivă, extensia procesului tumoral se realizează rapid, atât în suprafață, cât și în profunzime."},{"id":"C","text":"Progresia tumorii respectă strict limitarea anatomică a osului bazal, extinzându-se doar la nivel mucos."},{"id":"D","text":"Tumora evoluează exclusiv sub o formă cu extindere profundă asimptomatică."},{"id":"E","text":"Osteoliza secundară proliferării tumorale ia un aspect crateriform."}],"correct":["A","B","E"],"pages":[648],"source":"set-2"},{"id":"set2-z8eYxeK_","fingerprint":"fe9b77f3a17a0b64","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care este o afirmație corectă privind incidența și extinderea tumorilor maligne ale mucoasei gingivale?","options":[{"id":"A","text":"Tumorile maligne primare cu localizare strictă la nivelul mucoasei gingivale sunt formațiuni relativ rare."},{"id":"B","text":"Procesele tumorale primare din planșeul bucal nu se extind niciodată către mucoasa gingivală din cauza rezistenței ligamentului parodontal."},{"id":"C","text":"Majoritatea tumorilor gingivale maligne au originea într-un proces endoos aflat în stadiu incipient, neexteriorizat."},{"id":"D","text":"Extensia secundară a unui proces tumoral de vecinătate la nivel gingival este o situație excepțională."},{"id":"E","text":"Afectarea fibromucoasei palatine acționează ca o barieră naturală împotriva diseminării secundare la nivel gingival."}],"correct":["A"],"pages":[648],"source":"set-2"},{"id":"set2-Rfzkqx7r","fingerprint":"05074e2fbc5595b5","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afirmații referitoare la epidemiologia și prognosticul carcinoamelor orale sunt adevărate?","options":[{"id":"A","text":"Rata de supraviețuire crește cu peste 50% odată cu apariția adenopatiei metastatice în stadiul N1."},{"id":"B","text":"Planșeul bucal reprezintă cea mai frecventă localizare a carcinoamelor orale, fiind urmat de limbă."},{"id":"C","text":"Aproape 40-50% dintre bolnavi se prezintă la medic în stadiile I sau II de boală."},{"id":"D","text":"Incidența tumorilor carcinomatoase orale este estimată la aproximativ 275.000 de noi cazuri pe an."},{"id":"E","text":"Rata metastazelor oculte în stadiul incipient al cancerului oral este cuprinsă între 20% și 40%."}],"correct":["C","D","E"],"pages":[645],"source":"set-2"},{"id":"set2-AabO7rVF","fingerprint":"e10fc65fed6b100e","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Conform principiilor generale ale tratamentului chirurgical cu intenție curativă, care este conduita adecvată în managementul tumorilor maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Compromisurile excizionale sunt indicate atunci când se urmărește facilitarea obținerii unui rezultat reconstructiv superior din punct de vedere funcțional."},{"id":"B","text":"Extirparea tumorii primare implică obținerea unor margini libere negative, acestea reprezentând limitele de siguranță oncologică absolut necesare."},{"id":"C","text":"Metoda de plastie reconstructivă se alege înaintea extirpării tumorii, având impact direct asupra tiparului de excizie."},{"id":"D","text":"Intervenția chirurgicală se limitează la extirparea tumorii primare, evidarea cervicală fiind considerată o abordare terapeutică facultativă amânată."},{"id":"E","text":"Plastia reconstructivă imediată facilitează inițierea precoce a radioterapiei post-operatorii și asigură o calitate optimă a vieții post-intervenționale."}],"correct":["B","C","E"],"pages":[645],"source":"set-2"},{"id":"set2-lvYUy2wM","fingerprint":"8d383d38b114b2ac","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt caracteristicile esențiale ale anatomiei regionale cervicale și ale diseminării patologiei maligne în teritoriul oro-maxilo-facial?","options":[{"id":"A","text":"Conduita terapeutică necesită o decizie singulară și o intervenție exclusivă a medicului chirurg oro-maxilo-facial."},{"id":"B","text":"Metastazele sunt alcătuite din complexe celulare cu o structură histologică radical diferită de cea a tumorii maligne de origine."},{"id":"C","text":"Diseminarea metastatică la distanță din teritoriul oro-maxilo-facial se produce exclusiv pe cale hematogenă."},{"id":"D","text":"Tumorile maligne oro-maxilo-faciale prezintă o creștere de tip infiltrativ-distructiv, asociată cu fenomenul de invazie locală a țesuturilor adiacente."},{"id":"E","text":"Regiunea cervicală găzduiește aproximativ o treime din totalitatea limfonodulilor organismului uman."}],"correct":["D","E"],"pages":[645],"source":"set-2"},{"id":"set2-CVNdifdN","fingerprint":"dd895cd82660d565","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care reprezintă cel mai semnificativ factor de prognostic în cazul pacienților diagnosticați cu cancer oral?","options":[{"id":"A","text":"Prezența metastazei ganglionare la momentul evaluării pacientului."},{"id":"B","text":"Extinderea leziunii primare la nivelul planșeului bucal."},{"id":"C","text":"Dimensiunea absolută a tumorii măsurată în timpul stadiului incipient I de evoluție."},{"id":"D","text":"Rata accelerată a diviziunii celulare la nivelul marginilor tumorale infiltrative."},{"id":"E","text":"Infiltrarea directă a structurilor osoase maxilare prin procesul de expansiune antistructurală."}],"correct":["A"],"pages":[645],"source":"set-2"},{"id":"set2-uq9250MF","fingerprint":"200c8a32cb8a0902","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt etapele specifice ce alcătuiesc obligatoriu intervenția chirurgicală cu intenție curativă aplicată tumorilor maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Plastia reconstructivă a defectului de substanță rezultat în urma manevrelor excizionale post-operatorii."},{"id":"B","text":"Abordarea curativă sau profilactică a limfonodulilor cervicali, manifestată prin evidarea zonelor limfoganglionare."},{"id":"C","text":"Extirparea leziunii tumorale primare asigurând existența unor margini libere negative din punct de vedere neoplazic."},{"id":"D","text":"Includerea imunoterapiei în timpul intervenției drept o etapă chirurgicală de maximă necesitate celulară."},{"id":"E","text":"Radioterapia realizată exclusiv anterior oricărui tip de plastie reconstructivă cu scopul reducerii masei tumorale primare."}],"correct":["A","B","C"],"pages":[645],"source":"set-2"},{"id":"set2-0931IQJx","fingerprint":"a42084fc65005812","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt afirmațiile adevărate privind epidemiologia și debutul tumorilor maligne ale buzelor?","options":[{"id":"A","text":"Sunt localizate în peste 80% din cazuri la nivelul buzei superioare."},{"id":"B","text":"Apar mai frecvent la vârste cuprinse între 50 și 60 de ani."},{"id":"C","text":"Debutul tumoral are loc de cele mai multe ori exclusiv sub formă ulcero-vegetantă."},{"id":"D","text":"Predomină la pacienții de sex feminin."},{"id":"E","text":"Elementul ce orientează diagnosticul prezumtiv în stadiile de debut este localizarea paramediană a tumorii."}],"correct":["B","E"],"pages":[646],"source":"set-2"},{"id":"set2-jSNCglAf","fingerprint":"d62037b81585a3a2","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt trăsăturile clinice ce caracterizează ulcerațiile tuberculoase în cadrul diagnosticului diferențial al leziunilor labiale?","options":[{"id":"A","text":"Baza leziunii este indurată, cartonată, având o culoare roșie intensă."},{"id":"B","text":"Perilezional sunt prezente granulații gălbui."},{"id":"C","text":"Afecțiunea debutează prin erupții veziculoase care se remit în maximum 14 zile."},{"id":"D","text":"Leziunile sunt acoperite de depozite murdare."},{"id":"E","text":"Ulcerațiile au un caracter suplu."}],"correct":["B","D","E"],"pages":[646],"source":"set-2"},{"id":"set2-opT7qdAJ","fingerprint":"1dd6ebae0a33094c","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Prin ce mecanism se produce afectarea osoasă indirectă în cazul evoluției tumorilor maligne ale buzelor?","options":[{"id":"A","text":"Răspândirea prin contiguitate cu invadarea inițială a vestibulului bucal și ulterior a arcului osos mentonier."},{"id":"B","text":"Extensia tumorală de-a lungul canalului mandibular alături de pachetul vasculo-nervos."},{"id":"C","text":"Extensia locală de tip terebrant cu interesarea succesivă a structurilor adiacente."},{"id":"D","text":"Efracționarea periostului și invazia corticalei de către adenopatia submandibulară secundară fixată."},{"id":"E","text":"Invazia osului din aproape în aproape de la nivelul feței mucozale."}],"correct":["D"],"pages":[646],"source":"set-2"},{"id":"set2-9p_e5CVI","fingerprint":"2cae3db9de5bc71f","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt caracteristicile diseminării limfatice și afectării metastatice în tumorile maligne de buză?","options":[{"id":"A","text":"În termen de doi ani, metastazele cervicale se dezvoltă la aproape toți pacienții."},{"id":"B","text":"Afectarea ganglionară inițială vizează cel mai frecvent nivelul II cervical."},{"id":"C","text":"Ganglionii cervicali palpabili sunt prezenți la primul consult în 10-15% din cazuri."},{"id":"D","text":"Recidivele tumorii primare se asociază cu o scădere a incidenței metastazelor ganglionare cervicale."},{"id":"E","text":"Metastazele cervicale apar în proporție de aproximativ 25% pe parcursul primului an de la diagnostic."}],"correct":["A","C","E"],"pages":[646],"source":"set-2"},{"id":"set2-dAAZdCOp","fingerprint":"9d53d5eddf146404","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele leziuni reprezintă tumori benigne utilizate în diagnosticul diferențial al tumorilor maligne labiale?","options":[{"id":"A","text":"Adenomul glandelor salivare mici."},{"id":"B","text":"Botriomicomul."},{"id":"C","text":"Șancrul primar."},{"id":"D","text":"Cheilita microbiană."},{"id":"E","text":"Limfangiomul."}],"correct":["A","B","E"],"pages":[646],"source":"set-2"},{"id":"set2-N4tnBEAd","fingerprint":"c15bb457871cf706","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afirmații caracterizează tabloul clinic inițial și evolutiv al tumorilor maligne ale limbii și planșeului bucal?","options":[{"id":"A","text":"Limba și planșeul bucal reprezintă cele mai rare localizări ale tumorilor maligne orale."},{"id":"B","text":"Sunt forme tumorale cu un grad foarte scăzut de invazivitate locală."},{"id":"C","text":"Evoluția în fazele de debut este marcată de simptomatologie dureroasă intensă."},{"id":"D","text":"Pacienții prezintă frecvent adenopatii metastatice în momentul primului consult medical."},{"id":"E","text":"Aceste neoplazii prezintă un caracter limfofil marcat."}],"correct":["D","E"],"pages":[646],"source":"set-2"},{"id":"set2-64-V9Ssu","fingerprint":"a18ac6c8235cd674","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt formele de debut ale tumorilor maligne situate la nivelul porțiunii orale a limbii și planșeului bucal?","options":[{"id":"A","text":"Formă vegetantă."},{"id":"B","text":"Leziuni ulcerative apărute frecvent pe un fond leucoplazic."},{"id":"C","text":"Leziuni ulcerative însoțite din primul moment de durere severă."},{"id":"D","text":"Formă nodulară intraparenchimatoasă."},{"id":"E","text":"Formațiuni chistice extinse per primam la nivelul spațiilor fasciale profunde."}],"correct":["A","B","D"],"pages":[646],"source":"set-2"},{"id":"set2-7Q06m_RE","fingerprint":"e27bb5400234fc29","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce aspecte patogenice și clinice sunt asociate manifestărilor inițiale ale tumorilor maligne de la nivelul limbii?","options":[{"id":"A","text":"Debutul nodular intraparenchimatos are exclusiv o etiologie metastatică, prin diseminare hematogenă din focar primar la distanță."},{"id":"B","text":"Ulcerațiile limbii nu au nicio corelație cu prezența unor factori iritativi de cauză dentară."},{"id":"C","text":"Durerea apărută ulterior la nivelul leziunilor ulcerative este asociată cu suprainfectarea acestora."},{"id":"D","text":"Debutul nodular este caracteristic în situația în care tumora are punctul de plecare la nivelul glandelor salivare accesorii."},{"id":"E","text":"Obturațiile rugoase, cu margini tăioase sau neregulate pot reprezenta factori iritativi asociați apariției ulcerațiilor."}],"correct":["C","D","E"],"pages":[646],"source":"set-2"},{"id":"set2-qScbGHXW","fingerprint":"804cdef507cc06ea","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt trăsăturile clinice specifice ulcerației tuberculoase de la nivel oral folosite în diagnosticul diferențial al tumorilor maligne?","options":[{"id":"A","text":"Prezintă perilezional granulațiile gălbui ale lui Trélat."},{"id":"B","text":"Se prezintă sub forma unei ulcerații cu fundul neted, curat, cu indurație limitată a bazei."},{"id":"C","text":"Baza ulcerației este suplă la palpare."},{"id":"D","text":"Este o ulcerație de mici dimensiuni, care se remite în 7-10 zile."},{"id":"E","text":"Este frecvent situată pe fața dorsală a limbii."}],"correct":["A","C","E"],"pages":[647],"source":"set-2"},{"id":"set2-5EeeI3Ek","fingerprint":"b03c7ff6357975a5","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce trăsături definesc forma infiltrativă, scleroasă a tumorilor maligne orale?","options":[{"id":"A","text":"Reprezintă forma clinică predominantă a tumorilor localizate paramedian la nivelul planșeului bucal."},{"id":"B","text":"Este caracteristică exclusiv localizărilor intraparenchimatoase linguale."},{"id":"C","text":"Infiltrează difuz întreg parenchimul lingual."},{"id":"D","text":"Are o evoluție rapidă, cu extindere precoce către amigdale și vălul palatin."},{"id":"E","text":"Prezintă un prognostic favorabil, comparativ cu formele ulcero-distructive."}],"correct":["B","C"],"pages":[647],"source":"set-2"},{"id":"set2-nYat4gug","fingerprint":"46731f41920367f0","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care ganglion limfatic este implicat constant în drenajul porțiunii anterioare a limbii și planșeului bucal anterior, conform autorilor americani?","options":[{"id":"A","text":"Ganglionul submandibular principal"},{"id":"B","text":"Ganglionul jugulodigastric"},{"id":"C","text":"Ganglionul retrodigastric Kuttner I"},{"id":"D","text":"Ganglionul supraomohioidian"},{"id":"E","text":"Ganglionul cervical profund inferior"}],"correct":["D"],"pages":[647],"source":"set-2"},{"id":"set2-_5dFoQzc","fingerprint":"029e38f51299004f","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care afirmații sunt valabile referitor la topografia și incidența localizărilor tumorilor maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Localizările tumorale cu extensie pelvilinguală capătă adesea un aspect clinic de „carte deschisă”."},{"id":"B","text":"Jumătate dintre tumorile maligne cu localizare linguală anterioară afectează marginile limbii."},{"id":"C","text":"Treizeci și cinci de procente dintre tumorile maligne linguale interesează porțiunea limbii situată înapoia „V”-ului lingual."},{"id":"D","text":"Localizările de la nivelul feței dorsale a limbii sunt mai frecvente comparativ cu cele de pe fața ventrală."},{"id":"E","text":"Majoritatea tumorilor maligne ale planșeului bucal sunt situate paramedian în porțiunea anterioară a acestuia."}],"correct":["A","B","E"],"pages":[647],"source":"set-2"},{"id":"set2-t8FfTHcy","fingerprint":"b050a70a28bfc11d","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt particularitățile clinice și evolutive ale tumorilor porțiunii post-sulcale a limbii?","options":[{"id":"A","text":"Sunt tumori cu evoluție lentă, având multiple opțiuni terapeutice curative."},{"id":"B","text":"Prezintă un grad înalt de malignitate locală și asociază o metastazare precoce."},{"id":"C","text":"Debutul bolii este acut și zgomotos, diagnosticul fiind stabilit foarte precoce."},{"id":"D","text":"Manifestarea clinică subiectivă inițială este frecvent reprezentată de jena în deglutiție."},{"id":"E","text":"Examenul clinic obiectivează creșterea de volum a treimii posterioare a limbii, arie care devine dureroasă la presiune."}],"correct":["B","D","E"],"pages":[647],"source":"set-2"},{"id":"set2-02iMs5oN","fingerprint":"75337c99a26fe2b4","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Invazia căror structuri nervoase determină limitarea majoră a actelor funcționale și instalarea simptomatologiei algice severe în tumorile maligne pelvilinguale avansate?","options":[{"id":"A","text":"Nervul vag și nervul laringeu recurent"},{"id":"B","text":"Nervul hipoglos și nervul facial"},{"id":"C","text":"Nervul alveolar inferior și nervul trigemen"},{"id":"D","text":"Nervul lingual și nervul glosofaringian"},{"id":"E","text":"Nervul maxilar și nervul oftalmic"}],"correct":["D"],"pages":[647],"source":"set-2"},{"id":"set2-tnILaH6s","fingerprint":"555e4042377032a1","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt particularitățile formelor de debut ale tumorilor maligne primare ale mucoasei gingivale?","options":[{"id":"A","text":"La pacientul edentat, forma ulcerativă debutează invariabil cu o simptomatologie algică intensă."},{"id":"B","text":"La pacientul dentat, forma vegetantă papilomatoasă se dezvoltă frecvent în legătură cu o papilă interdentară, având inițial o bază mică de implantare."},{"id":"C","text":"Formele de debut sunt reprezentate de forma ulcero-distructivă și forma ulcero-vegetantă."},{"id":"D","text":"Formele maligne la pacientul edentat sunt adesea adiacente sau inclavate într-o arie de leucoplazie."},{"id":"E","text":"Mobilizarea dinților adiacenți este determinată de proliferarea tumorală de-a lungul ligamentului parodontal."}],"correct":["B","D","E"],"pages":[648],"source":"set-2"},{"id":"set2-CqLMNELd","fingerprint":"5b72713a0d50d8a8","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele aspecte caracterizează evoluția clinică în perioada de stare a tumorilor maligne ale mucoasei gingivale?","options":[{"id":"A","text":"În forma ulcero-distructivă, invazia osului subiacent se realizează exclusiv pe cale transmucoasă, evitând spațiul parodontal."},{"id":"B","text":"Forma ulcero-vegetantă se caracterizează printr-un aspect exofitic, conopidiform, cu păstrarea absolută a integrității osului subiacent."},{"id":"C","text":"Tumora evoluează sub două forme clinice principale: forma ulcero-distructivă și forma ulcero-vegetantă."},{"id":"D","text":"Mobilitatea dentară accentuată fără cauze odonto-parodontale dispare complet odată cu intrarea tumorii în perioada de stare."},{"id":"E","text":"Osteoliza secundară ia un aspect crateriform, osul putând fi acoperit de țesut granulativ sau rămânând denudat."}],"correct":["C","E"],"pages":[648],"source":"set-2"},{"id":"set2-oF69zr_T","fingerprint":"465f7a51f2f3c519","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce elemente de diagnostic și prognostic diferențiază tumorile maligne ale gingivomucoasei în funcție de caracteristicile topografice și histologice?","options":[{"id":"A","text":"Invazia osului crestei alveolare subiacente este un proces excepțional, prezent doar în stadii terminale ale tumorilor ulcero-vegetante."},{"id":"B","text":"Tumorile gingivo-mucoasei crestei alveolare mandibulare prezintă un caracter limfofil mult mai pronunțat decât cele maxilare."},{"id":"C","text":"Prognosticul tumorilor localizate la nivelul crestei alveolare mandibulare este considerabil mai favorabil comparativ cu cele maxilare."},{"id":"D","text":"Diagnosticul diferențial include tumori benigne sau maligne cu debut endoosos și tumori de granulație nespecifice, precum epulidele."},{"id":"E","text":"Majoritatea absolută a formațiunilor maligne întâlnite la nivelul mucoasei gingivale au o origine primară la acest nivel."}],"correct":["B","D"],"pages":[649],"source":"set-2"},{"id":"set2-bTxcAOg_","fingerprint":"6ed5049070650c0d","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Prin ce mecanism fiziopatologic local se explică instalarea mobilității dinților adiacenți în cazul formei vegetante a tumorilor maligne primare ale mucoasei gingivale la pacientul dentat?","options":[{"id":"A","text":"Prin necroza aseptică a pulpei dentare cu distrucție coronară secundară masivă."},{"id":"B","text":"Prin resorbția cimentului radicular indusă direct de o reacție autoimună locală la antigenele tumorale."},{"id":"C","text":"Prin presiunea mecanică exercitată de hiperplazia compensatorie a mucoasei jugale de vecinătate."},{"id":"D","text":"Prin proliferarea masei tumorale de-a lungul ligamentului parodontal."},{"id":"E","text":"Prin invazia directă și exclusivă a canalului radicular de către celulele maligne anaplazice."}],"correct":["D"],"pages":[648],"source":"set-2"},{"id":"set2-tz73WX8W","fingerprint":"850a34c6610cde8a","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afirmații sunt valabile în ceea ce privește osteosarcomul cu localizare mandibulară?","options":[{"id":"A","text":"Retinoblastomul este incriminat ca factor etiologic, conferind un risc de 7% pentru dezvoltarea bolii."},{"id":"B","text":"Cel mai adesea tumora își are originea în zona medulară centrală a corpului mandibulei."},{"id":"C","text":"Formele histologice anaplastice și teleangiectazice cumulează împreună peste 40% din totalitatea cazurilor."},{"id":"D","text":"Boala Paget și iradierea reprezintă factori incriminați în etiopatogenia tumorii."},{"id":"E","text":"Apare mai frecvent la femei, în special în jurul vârstei de 25-30 de ani."}],"correct":["A","B","D"],"pages":[649],"source":"set-2"},{"id":"set2-sobK_vaC","fingerprint":"8fea765b331021dc","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Sarcomul Ewing la nivelul oaselor maxilare prezintă următoarele caracteristici clinico-paraclinice:","options":[{"id":"A","text":"Afectează cu predilecție grupa de vârstă cuprinsă între 5 și 30 de ani, incidența la sexul masculin fiind dublă comparativ cu sexul feminin."},{"id":"B","text":"Examenul radiologic evidențiază o reacție periostală specifică denumită „triunghiurile lui Codman”."},{"id":"C","text":"Tumora este localizată cu predilecție la nivelul ramului ascendent al mandibulei."},{"id":"D","text":"Colorația PAS pune în evidență prezența unor cantități crescute de glicogen la nivelul insulelor de celule tumorale."},{"id":"E","text":"Febra, leucopenia, scăderea vitezei de sedimentare a hematiilor și trombocitopenia indică un prognostic rezervat."}],"correct":["A","D"],"pages":[650],"source":"set-2"},{"id":"set2-KoF8s47_","fingerprint":"0d6c9b1778402b52","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care este modificarea clinică întâlnită în mod caracteristic în stadiul de debut al tumorilor maligne primare de tip sarcomatos de la nivelul mandibulei?","options":[{"id":"A","text":"Deformarea corticalei vestibulare cu suprafață neregulată și consistență variabilă."},{"id":"B","text":"Mobilitatea dentară asociată cu dureri nevralgiforme, în absența semnelor de implicare odonto-parodontală."},{"id":"C","text":"Exteriorizarea prin alveola post-extracțională a unor burjoni tumorali cărnoși ca prim semn de boală."},{"id":"D","text":"Iradierea durerilor de mare intensitate în hemicraniu, însoțită de tulburări funcționale de fonație și deglutiție."},{"id":"E","text":"Exteriorizarea la nivelul cavității orale a unei mase tumorale cu aspect conopidiform, care ocupă șanțul mandibulo-lingual."}],"correct":["B"],"pages":[649],"source":"set-2"},{"id":"set2-6kFNufXr","fingerprint":"13d04c4c08111490","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Identificați afirmațiile care descriu corect aspectele radiologice ale formațiunilor tumorale maligne oro-maxilo-faciale:","options":[{"id":"A","text":"Carcinoamele odontogene cu evoluție rapidă se caracterizează printr-o radiotransparență difuză, cu margini neregulate."},{"id":"B","text":"Osteosarcomul poate fi descris printr-o imagine de radioopacitate neomogenă denumită „os pieptănat” sau „pernă cu ace”."},{"id":"C","text":"În formele cu evoluție lentă ale carcinoamelor odontogene, zona de radiotransparență este difuză și prezintă margini zimțate."},{"id":"D","text":"În procesele distructive osteolitice, precum și în osteosarcom, conturul osos este regulat, iar corticala este conservată."},{"id":"E","text":"Distrucția osoasă neregulată cu aspect în „raze de soare” indică prezența osteosarcomului prin formarea de spiculi cu orientare radiară."}],"correct":["A","B","E"],"pages":[650],"source":"set-2"},{"id":"set2-K2aTLMQD","fingerprint":"19c3be2f1f9d1d74","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt aserțiunile exacte referitoare la dezvoltarea și caracteristicile carcinoamelor odontogene?","options":[{"id":"A","text":"Reprezintă afecțiuni apărute cu o incidență net superioară la sexul feminin."},{"id":"B","text":"Pot lua naștere din membrana epitelială a chisturilor odontogene."},{"id":"C","text":"Sunt definite prin conexiunea inițială pe care o au cu mucoasa orală acoperitoare."},{"id":"D","text":"Constituie o formă de carcinoame spinocelulare cu debut endoosos."},{"id":"E","text":"Se pot dezvolta prin transformarea malignă a unui ameloblastom."}],"correct":["B","D","E"],"pages":[650],"source":"set-2"},{"id":"set2-W_952Y3n","fingerprint":"830f1576f145f0c4","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care dintre următoarele localizări anatomice corespunde tumorilor maligne de suprastructură, conform clasificării anatomo-clinice a lui Sebileau?","options":[{"id":"A","text":"Mucoasa gingivală a crestei alveolare mandibulare"},{"id":"B","text":"Regiunea exclusiv endosinuzală"},{"id":"C","text":"Zona etmoido-maxilară sau etmoido-maxilo-orbitală"},{"id":"D","text":"Platoul palato-alveolar"},{"id":"E","text":"Spațiul pterigomaxilar izolat"}],"correct":["C"],"pages":[651],"source":"set-2"},{"id":"set2-hktivO2R","fingerprint":"d944de97e04c1ce9","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt caracteristicile clinice și radiologice ale carcinomului adenoid chistic cu punct de plecare la nivelul platoului palato-alveolar?","options":[{"id":"A","text":"Se prezintă inițial sub forma unui nodul bine delimitat."},{"id":"B","text":"Radiologic, în perioada de stare determină o distrucție osoasă cu margini neregulate, în care dinții par a fi suspendați."},{"id":"C","text":"Prezintă o creștere lentă, progresivă, neînsoțită de acuze dureroase în stadiile inițiale."},{"id":"D","text":"Produce o ulcerație precoce pe versantul vestibular al crestei alveolare, însoțită de dureri violente."},{"id":"E","text":"Este localizat cel mai frecvent în treimea anterioară a palatului dur."}],"correct":["A","B","C"],"pages":[651],"source":"set-2"},{"id":"set2-UomSsEDJ","fingerprint":"258dbe2f8d9e35c0","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afirmații descriu tabloul clinic și conduita în cazul tumorilor maligne de mezostructură de tip carcinom?","options":[{"id":"A","text":"Rinoscopia anterioară evidențiază modificări strict limitate la nivelul meatului inferior."},{"id":"B","text":"Perioada de debut este marcată de secreții serosanguinolente sau seropurulente unilaterale, asociate cu mobilitate dentară."},{"id":"C","text":"Extracția dinților mobili este o etapă de primă intenție pentru drenajul focarului supurativ."},{"id":"D","text":"Un semn caracteristic în perioada de stare este hipoestezia nervului infraorbitar, cauzată de tropismul perineural."},{"id":"E","text":"Alveola postextracțională se umple cu muguri tumorali care sângerează spontan sau la cele mai mici traumatisme."}],"correct":["B","D","E"],"pages":[651],"source":"set-2"},{"id":"set2-aL8XfdxN","fingerprint":"9c052e557e8697c8","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"În evoluția tumorilor maligne de suprastructură de tip carcinom, invazia rapidă extensivă către baza craniului se realizează la nivelul cărei structuri anatomice?","options":[{"id":"A","text":"Fisurii orbitare superioare"},{"id":"B","text":"Proceselor pterigoide ale osului sfenoid"},{"id":"C","text":"Canalului optic"},{"id":"D","text":"Lamei ciuruite a osului etmoid"},{"id":"E","text":"Lamei perpendiculare a osului palatin"}],"correct":["D"],"pages":[651],"source":"set-2"},{"id":"set2-X0d1JMi9","fingerprint":"74309cc9915a7bff","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele elemente clinice și radiologice pot fi identificate în cazul tumorilor maligne de suprastructură?","options":[{"id":"A","text":"Tabloul clinic include apariția diplopiei, a exoftalmiei și diminuarea acuității vizuale."},{"id":"B","text":"Afectarea limfonodulară este un proces tardiv care se limitează la nivelele cervicale inferioare."},{"id":"C","text":"Examenul radiologic evidențiază opacifierea porțiunii supero-interne a sinusului maxilar."},{"id":"D","text":"Conturul orbitar se vizualizează radiologic cu un halou de osteoscleroză și limite clare."},{"id":"E","text":"Tegumentele din unghiul intern al orbitei suferă modificări, devenind roșii-violacee și prezentând ulcerații."}],"correct":["A","C","E"],"pages":[652],"source":"set-2"},{"id":"set2-oeza5i1g","fingerprint":"5c4f09a4ce8b3d4e","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care dintre următoarele caracteristici este specifică pentru capilarele și vasele limfatice?","options":[{"id":"A","text":"Capilarele limfatice au un diametru mai mic decât capilarele sanguine."},{"id":"B","text":"La nivelul ganglionului pătrund multiple vase aferente și pleacă multiple vase eferente."},{"id":"C","text":"Capilarele limfatice au un calibru uniform și realizează anastomoze rare între ele."},{"id":"D","text":"Capilarele limfatice prezintă la interior valve semilunare cu marginea liberă orientată spre lumenul vasului."},{"id":"E","text":"Vasele limfatice superficiale sunt situate profund de fascia superficială, la nivelul musculaturii."}],"correct":["D"],"pages":[652],"source":"set-2"},{"id":"set2-KVFIB8g3","fingerprint":"d33b393bb144e19f","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la structura și circulația limfei la nivelul ganglionului limfatic?","options":[{"id":"A","text":"Structura ganglionului limfatic este alcătuită din capsula conjunctivă, alături de ariile corticală, paracorticală și medulară."},{"id":"B","text":"Limfa trece din limfaticele aferente direct în vasul eferent, ocolind sinusurile medulare."},{"id":"C","text":"Căile de circulație intraparenchimatoasă sunt lipsite de septuri, favorizând un flux limfatic rapid fără filtrare."},{"id":"D","text":"Vasul eferent iese din ganglion la nivelul hilului, având dimensiuni mai mari decât vasele aferente."},{"id":"E","text":"Limfa pătrunde inițial din vasele aferente în sinusul subcapsular, de unde se direcționează către sinusurile medulare."}],"correct":["A","D","E"],"pages":[652],"source":"set-2"},{"id":"set2-jQupRRE3","fingerprint":"a195f702ce875c73","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce modificări pot fi induse la nivelul unui ganglion limfatic în urma unei agresiuni de natură inflamatorie sau tumorală malignă?","options":[{"id":"A","text":"Hiperplazia corticală"},{"id":"B","text":"Histiocitoza sinuzală"},{"id":"C","text":"Hipoplazia foliculară difuză"},{"id":"D","text":"Acumularea de numeroase histiocite la nivelul sinusurilor paracorticale"},{"id":"E","text":"Distrugerea capsulei conjunctive fără afectare medulară"}],"correct":["A","B","D"],"pages":[652],"source":"set-2"},{"id":"set2-rlBqmw5K","fingerprint":"acc19ecd185e5641","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Cum este interpretată prezența histiocitozei sinuzale la nivelul unui ganglion limfatic în contextul unei patologii oncologice?","options":[{"id":"A","text":"Indicând un ganglion reactiv la tumoră (pN0), constituie un indiciu pentru străbaterea acestuia de către clone tumorale."},{"id":"B","text":"Se caracterizează prin înlocuirea completă a ariilor corticale și medulare cu colonii tumorale maligne."},{"id":"C","text":"Reprezintă o certitudine a prezenței metastazei ganglionare, ganglionul fiind evaluat direct ca pN+."},{"id":"D","text":"Exclude posibilitatea unei metastaze ganglionare, făcând inutilă efectuarea testelor de imunohistochimie."},{"id":"E","text":"Este un fenomen asociat exclusiv cu infecțiile bacteriene, nefiind influențat de trecerea clonelor tumorale."}],"correct":["A"],"pages":[652],"source":"set-2"},{"id":"set2-nOkKeHdM","fingerprint":"fd2e9e4eb46fec90","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care este pragul profunzimii de invazie de la care tumorile maligne orale de tip carcinom spinocelular sunt considerate foarte limfofile?","options":[{"id":"A","text":"Peste 1 mm"},{"id":"B","text":"Peste 5 mm"},{"id":"C","text":"Peste 3 mm"},{"id":"D","text":"Peste 4 mm"},{"id":"E","text":"Peste 2 mm"}],"correct":["E"],"pages":[652],"source":"set-2"},{"id":"set2-2eD88zp-","fingerprint":"02b9abd23a0cabab","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afirmații referitoare la factorii determinanți ai diseminării metastatice a tumorilor maligne oro-maxilo-faciale sunt corecte?","options":[{"id":"A","text":"Tumorile bine sau moderat diferențiate (G1, G2) asociază o incidență mai mare a metastazelor față de cele slab diferențiate (G3, G4)."},{"id":"B","text":"Limfofilia tumorilor maligne orale de tip carcinom spinocelular este direct influențată de profunzimea invaziei."},{"id":"C","text":"Tumorile cu localizare posterioară în cavitatea orală prezintă un risc de diseminare metastatică mai mic decât cele anterioare."},{"id":"D","text":"Carcinoamele spinocelulare de bază de limbă cu grad mic de diferențiere pot genera adenopatie metastatică loco-regională încă din stadiul T1."},{"id":"E","text":"Forma histopatologică a tumorii primare reprezintă un factor de prognostic independent privind diseminarea metastatică."}],"correct":["B","D","E"],"pages":[652],"source":"set-2"},{"id":"set2-8oqYspH6","fingerprint":"f6dac8a1795ce410","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt caracteristicile invaziei perinervoase în patologia malignă oro-maxilo-facială?","options":[{"id":"A","text":"Reprezintă un factor independent de predicție pentru recidiva locală."},{"id":"B","text":"Prezența invaziei perinervoase nu influențează potențialul metastatic loco-regional."},{"id":"C","text":"Este o caracteristică binecunoscută a carcinomului adenoid chistic."},{"id":"D","text":"Mecanismul de invazie implică atât contiguitatea, cât și embolizarea discontinuă."},{"id":"E","text":"Este o particularitate întâlnită exclusiv în cazul carcinomului spinocelular."}],"correct":["A","C","D"],"pages":[653],"source":"set-2"},{"id":"set2-QaIXLedt","fingerprint":"1ea48bd641a8a42e","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"În ce situație stadiul T (dimensiunea tumorii primare) își pierde din relevanță în privința incidenței metastazelor, datorită limfofiliei extreme?","options":[{"id":"A","text":"În cazul prezenței carcinomului adenoid chistic limitat la structurile nervoase periferice."},{"id":"B","text":"În tumorile cu localizare strictă la nivelul buzei, indiferent de forma histopatologică."},{"id":"C","text":"În carcinoamele spinocelulare de bază de limbă, cu grad mic de diferențiere."},{"id":"D","text":"În carcinoamele bine diferențiate (G1) cu localizare anterioară în cavitatea orală."},{"id":"E","text":"În tumorile care prezintă o invazie în profunzime de sub 2 mm."}],"correct":["C"],"pages":[652],"source":"set-2"},{"id":"set2-iCtvEvAV","fingerprint":"eae39415a5698587","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt factorii ce asociază o creștere a riscului de diseminare metastatică în tumorile maligne oro-maxilo-faciale?","options":[{"id":"A","text":"Localizarea tumorii primare în porțiunea posterioară a cavității orale."},{"id":"B","text":"Prezența invaziei perinervoase prin embolizare discontinuă."},{"id":"C","text":"Încadrarea tumorii în categoria carcinoamelor bine sau moderat diferențiate (G1, G2)."},{"id":"D","text":"Încadrarea tumorii în gradul de diferențiere histologică G3 sau G4."},{"id":"E","text":"Invazia tumorală limitată la o profunzime de până la 2 mm."}],"correct":["A","B","D"],"pages":[653],"source":"set-2"},{"id":"set2-KNaryMMc","fingerprint":"82357f4e2acabb70","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce situații poate indica absența ganglionilor cervicali palpabili în context oncologic?","options":[{"id":"A","text":"Existența unui ganglion metastatic ce a rupt capsula."},{"id":"B","text":"Lipsa afectării metastatice."},{"id":"C","text":"Existența unei microadenopatii metastatice."},{"id":"D","text":"Prezența unui ganglion reactiv de mici dimensiuni."},{"id":"E","text":"Fixarea ganglionară la structurile de vecinătate."}],"correct":["B","C","D"],"pages":[653],"source":"set-2"},{"id":"set2-Flzl1KSv","fingerprint":"be12df34c20469bf","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt procesele patologice asociate cu evoluția dezvoltării coloniei metastatice ganglionare cervicale?","options":[{"id":"A","text":"Invazia și ruptura capsulei ganglionare."},{"id":"B","text":"Transformarea ganglionului metastatic într-un ganglion exclusiv reactiv."},{"id":"C","text":"Invazia structurilor de vecinătate, precum vasele, tegumentul și structurile osoase."},{"id":"D","text":"Asocierea cu un prognostic clinic favorabil."},{"id":"E","text":"Fixarea ganglionului limfatic."}],"correct":["A","C","E"],"pages":[653],"source":"set-2"},{"id":"set2-MqMD2WDC","fingerprint":"a4013573c6805ca8","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt criteriile dimensionale și celulare descrise în cazul ganglionilor limfatici cervicali evaluați clinic?","options":[{"id":"A","text":"Ganglionii limfatici necesită un diametru minim de 1 cm pentru a fi decelabili prin palpare."},{"id":"B","text":"Ganglionii limfatici cu un diametru sub 0,5 cm sunt întotdeauna palpabili dacă sunt metastatici."},{"id":"C","text":"Un ganglion metastatic poate conține până la 10⁹ celule tumorale pentru a deveni palpabil."},{"id":"D","text":"Un ganglion cervical palpabil este întotdeauna un ganglion metastatic în context oncologic."},{"id":"E","text":"Absența ganglionilor cu diametrul peste 1 cm exclude prezența celulelor tumorale."}],"correct":["A","C"],"pages":[653],"source":"set-2"},{"id":"set2-iIIoA8iP","fingerprint":"fee9a8d6071406ec","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Ce particularități prezintă adenopatia cervicală în contextul identificării unei tumori maligne?","options":[{"id":"A","text":"Prezența adenopatiei cervicale asociată cu factori de risc ridică suspiciunea de tumoră malignă ocultă."},{"id":"B","text":"Impune efectuarea de investigații suplimentare pentru decelarea tumorii primare, în caz de suspiciune de tumoră ocultă."},{"id":"C","text":"Poate constitui singura manifestare clinică a unei tumori maligne."},{"id":"D","text":"Reprezintă un stadiu evolutiv caracterizat obligatoriu prin invazia osoasă chiar de la dimensiuni de sub 1 cm."},{"id":"E","text":"Lipsa adenopatiei palpabile exclude necesitatea investigațiilor suplimentare la pacienții cu factori de risc oncologic."}],"correct":["A","B","C"],"pages":[653],"source":"set-2"},{"id":"set2-qF4rBaUw","fingerprint":"d3da9afb964a22d8","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele afecțiuni sunt clasificate drept adenite inflamatorii și/sau imunologice în cadrul diagnosticului diferențial al adenopatiilor metastatice cervicale?","options":[{"id":"A","text":"Boala Kawasaki"},{"id":"B","text":"Lupusul eritematos diseminat"},{"id":"C","text":"Histiocitoza X"},{"id":"D","text":"Macroglobulinemia Waldenstrom"},{"id":"E","text":"Limforeticuloza benignă de inoculare"}],"correct":["A","B","C"],"pages":[653],"source":"set-2"},{"id":"set2-uL-08yMW","fingerprint":"038c4cc3d76d4092","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care sunt posibilitățile structurate de algoritmul terapeutic internațional pentru abordarea stadiului N₀ (limfonoduli nedecelabili clinic și/sau imagistic)?","options":[{"id":"A","text":"Radioterapia cervicală profilactică"},{"id":"B","text":"Evidarea cervicală terapeutică"},{"id":"C","text":"Monitorizarea activă"},{"id":"D","text":"Evidarea cervicală profilactică"},{"id":"E","text":"Chimioterapia sistemică profilactică"}],"correct":["A","C","D"],"pages":[654],"source":"set-2"},{"id":"set2-kX0SrOvn","fingerprint":"b255805baefeeb09","chapterId":"set-2","subchapterId":"set2-7.23","type":"CS","text":"Care dintre următoarele formațiuni reprezintă o tumoră malignă cervicală neganglionară în contextul diagnosticului diferențial al adenopatiilor metastatice cervicale?","options":[{"id":"A","text":"Carcinomul chistic al canalului tireoglos"},{"id":"B","text":"Teratomul"},{"id":"C","text":"Neurofibromul"},{"id":"D","text":"Chistul canalului tireoglos"},{"id":"E","text":"Tumora de glomus carotic"}],"correct":["A"],"pages":[653],"source":"set-2"},{"id":"set2-Z8CCcXbn","fingerprint":"27d5bbb6d20d509d","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele infecții reprezintă cauze virale ale limfadenitelor cervicale din cadrul diagnosticului diferențial al metastazelor ganglionare?","options":[{"id":"A","text":"Rubeola"},{"id":"B","text":"Toxoplasmoza"},{"id":"C","text":"Tularemia"},{"id":"D","text":"Limforeticuloza benignă de inoculare (Debré)"},{"id":"E","text":"Mononucleoza infecțioasă"}],"correct":["A","D","E"],"pages":[653],"source":"set-2"},{"id":"set2-IZ_VZOBd","fingerprint":"4eaed7e6644b0bba","chapterId":"set-2","subchapterId":"set2-7.23","type":"CM","text":"Care dintre următoarele substanțe medicamentoase pot provoca limfadenite medicamentoase luate în considerare în diagnosticul diferențial al adenopatiilor cervicale metastatice?","options":[{"id":"A","text":"Aspirina"},{"id":"B","text":"Meprobamatul"},{"id":"C","text":"Heparina"},{"id":"D","text":"Streptomicina"},{"id":"E","text":"Penicilina"}],"correct":["B","C","D","E"],"pages":[653],"source":"set-2"}];
